function portraitKey(key){ return String(key).replace(/[\/\\:]/g,'_'); }
function artUrl(key){
  if(IMG_BASE) return IMG_BASE + '/art/' + key + '.png';
  const k = portraitKey(key);
  return HAS_PORTRAIT.has(k) ? ('/assets/portraits/' + k + '.jpg') : '';
}
